module contract;


// Trusted resource-projection assumptions, vocabulary version 1.
// These preserve the Cycle 19 audit table; they do not verify the C bodies.
// Borrowed scalar/opaque arguments carry no resource custody requirement.
// Detailed observation/lifecycle contracts remain separate semantic profiles.
//
// Card CONTRACT-INHERIT-ADOPTION: Fluent Bit's allocator wrappers take their
// contracts from the libc declarations they wrap instead of restating them.
// `include/fluent-bit/flb_mem.h` defines `flb_malloc` as `size == 0 -> NULL`,
// then `malloc(size)`; `flb_calloc` as `size == 0 -> NULL`, then
// `calloc(n, size)`; and `flb_free` as `free(ptr)` (the OSS-Fuzz arms are not
// in the audited build). The `size == 0` guard returns NULL, which the
// `nullable` owned result already covers, so the custody statement is the
// parent's exactly. Each elaborates to the clauses these declarations carried
// when they were written out by hand (clause for clause, parameter names
// included); an inherited contract is a trusted assumption of the same
// strength as that hand-written one, never a proof.

extern fn flb_malloc(size: usize) -> ptr<mut, u8> contract { requires resource_contract_v1; ensures normal resource_borrowed(size); ensures normal resource_return_owned(nullable); };

extern fn flb_calloc(count: usize, size: usize) -> ptr<mut, u8> contract { requires resource_contract_v1; ensures normal resource_borrowed(count); ensures normal resource_borrowed(size); ensures normal resource_return_owned(nullable); };

extern fn flb_free(ptr: ptr<mut, u8>) -> unit contract { requires resource_contract_v1; ensures normal resource_released(ptr, nullable); ensures normal resource_return_none(); };

// Card LOADER-ABI: `len` is `int`, not a size. Upstream declares
// `flb_sds_t flb_sds_create_len(const char *str, int len);`
// (`include/fluent-bit/flb_sds.h:99` at the pinned revision) and defines it with
// the same signature; the earlier `usize` here was an unfaithful projection,
// found by the declared/C ABI comparison and corrected against the read body.
// The mode is unchanged: a scalar carries no custody either way.
extern fn flb_sds_create_len(str: ptr<const, u8>, len: i32) -> ptr<mut, u8>
contract {
    requires resource_contract_v1;
    ensures normal resource_borrowed(str);
    ensures normal resource_borrowed(len);
    ensures normal resource_return_owned(nullable);
};

// Fluent Bit's own function (it frees the header in front of the string, not
// the pointer it is given), so it stays written out even though its clauses
// coincide with `libc::free`'s: an inherited contract tracks its parent, and
// this one must not.
extern fn flb_sds_destroy(ptr: ptr<mut, u8>) -> unit
contract {
    requires resource_contract_v1;
    ensures normal resource_released(ptr, nullable);
    ensures normal resource_return_none();
};

module contract;


// Trusted resource-projection assumptions, vocabulary version 1.
//
// Card CONTRACT-INHERIT-ADOPTION (user-directed declared assumptions for later
// corpus scope). Fluent Bit's string-duplication helpers take the custody
// statements of the libc functions they stand for:
//
//   static inline char *flb_strndup(const char *s, size_t n)
//     -- `flb_malloc(n + 1)`, NULL on failure, else `memcpy(str, s, n)` and a
//        terminator (`include/fluent-bit/flb_str.h`).
//   static inline char *flb_strdup(const char *s)
//     -- `flb_strndup(s, strlen(s))`.
//
// Each reads its string (borrowed), takes a size by value (borrowed) and
// returns a fresh `malloc` allocation or NULL: the caller acquires an
// obligation that `flb_free`/`free` discharges. That is `libc::strdup`'s and
// `libc::strndup`'s statement exactly, so the contracts are inherited rather
// than restated. `flb_strndup` is NOT a byte-exact forward of `strndup` (it
// copies exactly `n` bytes with `memcpy` instead of stopping at a terminator,
// and allocates through `flb_malloc`); the custody statement, which is all
// resource v1 says, is the same.
//
// These are TRUSTED ASSUMPTIONS over code the analyzer could read: both bodies
// are `static inline` in a header every including unit carries. Wherever this
// module is selected, the contract stands in for the body at every call site.

extern fn flb_strdup(s: ptr<const, u8>) -> ptr<mut, u8> contract { requires resource_contract_v1; ensures normal resource_borrowed(s); ensures normal resource_return_owned(nullable); };

extern fn flb_strndup(s: ptr<const, u8>, n: usize) -> ptr<mut, u8> contract { requires resource_contract_v1; ensures normal resource_borrowed(s); ensures normal resource_borrowed(n); ensures normal resource_return_owned(nullable); };

